// Generated by GitHub Copilot - Oct-02-2026
/**
 * Pulls live odds from Polymarket, Kalshi and Decision Desk HQ and writes public/data/snapshot.json.
 * Runs in CI (GitHub Actions cron) because Kalshi/DDHQ do not allow browser CORS requests.
 * Exits non-zero when every live source fails so a broken snapshot is never deployed.
 */
import { mkdir, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { DDHQ_FALLBACK, DDHQ_SWEEP_ANCHOR, ELECTION_DATE, RACES, SOURCE_META, STATIC_SOURCES } from '../src/config';
import { estimateSweep } from '../src/lib/analysis';
import { findByTickerSuffix, parseKalshiCandles, parseKalshiEvent, parseKalshiEvents } from '../src/lib/sources/kalshi';
import { findOutcome, parsePolymarketEvent, parsePolymarketHistory } from '../src/lib/sources/polymarket';
import { parseDdhq, parseHillForecast, type DdhqForecast } from '../src/lib/sources/ddhq';
import { SnapshotSchema, type Point, type Race, type Series, type Snapshot, type Source } from '../src/types';

const OUT = resolve(dirname(fileURLToPath(import.meta.url)), '../public/data/snapshot.json');
const HISTORY_START = Date.parse('2026-01-01T00:00:00Z') / 1000;
const MAX_BYTES = 5 * 1024 * 1024;
const ALLOWED_HOSTS = new Set([
  'gamma-api.polymarket.com',
  'clob.polymarket.com',
  'api.elections.kalshi.com',
  'votes.decisiondeskhq.com',
  'elections2026.thehill.com',
]);
const POLY = 'https://gamma-api.polymarket.com';
const CLOB = 'https://clob.polymarket.com';
const KALSHI = 'https://api.elections.kalshi.com/trade-api/v2';
const HILL = 'https://elections2026.thehill.com/api/forecast/2026';

/** GET with host allow-list, timeout, size cap and one retry. */
async function get(url: string, as: 'json' | 'text' = 'json'): Promise<unknown> {
  const { hostname, protocol } = new URL(url);
  if (protocol !== 'https:' || !ALLOWED_HOSTS.has(hostname)) throw new Error(`blocked host ${hostname}`);
  let lastErr: unknown;
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const res = await fetch(url, {
        signal: AbortSignal.timeout(20_000),
        headers: { Accept: as === 'json' ? 'application/json' : 'text/html', 'User-Agent': 'midterms-sweep-tracker/1.0' },
      });
      if (!res.ok) throw new Error(`HTTP ${res.status} for ${url}`);
      const body = await res.text();
      if (body.length > MAX_BYTES) throw new Error(`response too large for ${url}`);
      return as === 'json' ? JSON.parse(body) : body;
    } catch (err) {
      lastErr = err;
    }
  }
  throw lastErr;
}

const sinceStart = (pts: Point[]) =>
  pts.filter((x) => x.t >= HISTORY_START).map((x) => ({ t: x.t, p: Math.round(x.p * 1000) / 1000 }));

const errMsg = (e: unknown) => (e instanceof Error ? e.message : String(e)).slice(0, 200);

function failed(id: 'polymarket' | 'kalshi' | 'ddhq', e: unknown): Source {
  return { id, ...SOURCE_META[id], freshness: 'live', asOf: new Date().toISOString(), status: 'error', error: errMsg(e), house: null, senate: null, sweep: null };
}

interface ProviderResult {
  source: Source;
  races: Map<string, number>;
  history: Partial<Record<keyof Snapshot['history'], Point[]>>;
}

async function polymarket(): Promise<ProviderResult> {
  const event = async (slug: string) => parsePolymarketEvent(await get(`${POLY}/events?slug=${encodeURIComponent(slug)}`));
  const history = async (token: string | null | undefined) =>
    token ? sinceStart(parsePolymarketHistory(await get(`${CLOB}/prices-history?market=${encodeURIComponent(token)}&interval=max&fidelity=1440`))) : [];

  const balance = await event('balance-of-power-2026-midterms');
  const house = await event('which-party-will-win-the-house-in-2026');
  const senate = await event('which-party-will-win-the-senate-in-2026');
  const sweep = findOutcome(balance, 'democrats sweep');
  const houseD = findOutcome(house, 'democratic');
  const senateD = findOutcome(senate, 'democratic');
  if (!sweep || !houseD || !senateD) throw new Error('expected outcomes missing');

  const races = new Map<string, number>();
  for (const race of RACES) {
    try {
      const o = findOutcome(await event(race.polymarketSlug), race.dem.split(' ').at(-1)!);
      if (o) races.set(race.state, o.p);
    } catch (e) {
      console.warn(`polymarket ${race.state}: ${errMsg(e)}`);
    }
  }

  return {
    source: {
      id: 'polymarket', ...SOURCE_META.polymarket, freshness: 'live', asOf: new Date().toISOString(), status: 'ok',
      house: houseD.p, senate: senateD.p, sweep: sweep.p, volumeUsd: balance.volumeUsd,
    },
    races,
    history: {
      sweep: await history(sweep.yesTokenId),
      senate: await history(senateD.yesTokenId),
      house: await history(houseD.yesTokenId),
    },
  };
}

async function kalshi(): Promise<ProviderResult> {
  const events = async (series: string) => get(`${KALSHI}/events?series_ticker=${encodeURIComponent(series)}&with_nested_markets=true&status=open`);
  const candles = async (series: string, ticker: string) => {
    const now = Math.floor(Date.now() / 1000);
    const url = `${KALSHI}/series/${encodeURIComponent(series)}/markets/${encodeURIComponent(ticker)}/candlesticks?start_ts=${HISTORY_START}&end_ts=${now}&period_interval=1440`;
    try {
      return sinceStart(parseKalshiCandles(await get(url)));
    } catch (e) {
      console.warn(`kalshi candles ${ticker}: ${errMsg(e)}`);
      return [];
    }
  };

  const comboEvents = parseKalshiEvents(await events('KXBALANCEPOWERCOMBO'));
  const combo = [...comboEvents.values()].find((ms) => ms.some((m) => m.ticker.endsWith('-DD')));
  const sweep = combo && findByTickerSuffix(combo, '-DD');
  const house = findByTickerSuffix(parseKalshiEvent(await events('CONTROLH'), 'CONTROLH-2026'), '-D');
  const senate = findByTickerSuffix(parseKalshiEvent(await events('CONTROLS'), 'CONTROLS-2026'), '-D');
  if (!sweep || !house || !senate) throw new Error('expected markets missing');

  const races = new Map<string, number>();
  for (const race of RACES) {
    try {
      const d = findByTickerSuffix(parseKalshiEvent(await events(race.kalshiEvent.replace(/-\d+$/, '')), race.kalshiEvent), '-D');
      if (d) races.set(race.state, d.p);
    } catch (e) {
      console.warn(`kalshi ${race.state}: ${errMsg(e)}`);
    }
  }

  return {
    source: {
      id: 'kalshi', ...SOURCE_META.kalshi, freshness: 'live', asOf: new Date().toISOString(), status: 'ok',
      house: house.p, senate: senate.p, sweep: sweep.p,
    },
    races,
    history: {
      sweep: await candles('KXBALANCEPOWERCOMBO', sweep.ticker),
      senate: await candles('CONTROLS', senate.ticker),
      house: await candles('CONTROLH', house.ticker),
    },
  };
}

/** DDHQ via its media partner The Hill; used when votes.decisiondeskhq.com blocks bots. Has no sweep figure. */
async function hill(): Promise<DdhqForecast> {
  const house = parseHillForecast(await get(`${HILL}/house`), 'house');
  const senate = parseHillForecast(await get(`${HILL}/senate`), 'senate');
  return {
    house: house.p, senate: senate.p, sweep: null,
    updatedAt: senate.updatedAt ?? house.updatedAt,
    houseHistory: house.history, senateHistory: senate.history,
  };
}

async function ddhq(): Promise<ProviderResult> {
  let f: DdhqForecast;
  try {
    f = parseDdhq((await get(SOURCE_META.ddhq.url, 'text')) as string);
  } catch (e) {
    console.warn(`ddhq direct failed (${errMsg(e)}); trying The Hill`);
    f = await hill();
  }
  const asOf = f.updatedAt ? new Date(`${f.updatedAt.replace(' ', 'T').slice(0, 19)}Z`).toISOString() : new Date().toISOString();
  const sweepEstimated = f.sweep === null;
  const sweep = f.sweep ?? Math.round(estimateSweep(f.house, f.senate, DDHQ_SWEEP_ANCHOR) * 1000) / 1000;
  return {
    source: { id: 'ddhq', ...SOURCE_META.ddhq, freshness: 'live', asOf, status: 'ok', house: f.house, senate: f.senate, sweep, ...(sweepEstimated && { sweepEstimated }) },
    races: new Map(),
    history: { senate: sinceStart(f.senateHistory), house: sinceStart(f.houseHistory) },
  };
}

async function main(): Promise<void> {
  const providers = { polymarket, kalshi, ddhq } as const;
  const ids = Object.keys(providers) as (keyof typeof providers)[];
  const settled = await Promise.allSettled(ids.map((id) => providers[id]()));
  const results = settled.map((r, i): ProviderResult => {
    if (r.status === 'fulfilled') return r.value;
    console.error(`${ids[i]} failed: ${errMsg(r.reason)}`);
    return { source: failed(ids[i]!, r.reason), races: new Map(), history: {} };
  });

  if (results.every((r) => r.source.status === 'error')) {
    console.error('All live sources failed; refusing to write snapshot.');
    process.exit(1);
  }

  const ddhqResult = results.find((r) => r.source.id === 'ddhq');
  if (ddhqResult?.source.status === 'error') {
    console.warn(`ddhq: using static fallback from ${DDHQ_FALLBACK.asOf}`);
    ddhqResult.source = DDHQ_FALLBACK;
  }

  const byId = (id: string) => results.find((r) => r.source.id === id);
  const races: Race[] = RACES.map((r) => ({
    state: r.state, name: r.name, dem: r.dem, rep: r.rep, heldBy: r.heldBy,
    kalshi: byId('kalshi')?.races.get(r.state) ?? null,
    polymarket: byId('polymarket')?.races.get(r.state) ?? null,
  }));
  const series = (chamber: keyof Snapshot['history']): Series[] =>
    results.flatMap((r) => {
      const points = r.history[chamber];
      return points?.length ? [{ sourceId: r.source.id, points }] : [];
    });

  const snapshot: Snapshot = SnapshotSchema.parse({
    generatedAt: new Date().toISOString(),
    electionDate: ELECTION_DATE,
    sources: [...results.map((r) => r.source), ...STATIC_SOURCES],
    races,
    history: { sweep: series('sweep'), senate: series('senate'), house: series('house') },
  });

  await mkdir(dirname(OUT), { recursive: true });
  await writeFile(OUT, JSON.stringify(snapshot));
  for (const s of snapshot.sources) {
    console.log(`${s.id.padEnd(10)} ${s.status.padEnd(5)} house=${s.house ?? '-'} senate=${s.senate ?? '-'} sweep=${s.sweep ?? '-'}`);
  }
  console.log(`Wrote ${OUT}`);
}

await main();
